class Circle
{
public:
    explicit Circle(double radius) : m_radius{ radius } {}

    double radius() { return m_radius; }
    double area() { return 3.14159 * m_radius * m_radius; }
    double circumference() { return 2 * 3.14159 * m_radius; }
    void setRadius(double radius) { m_radius = radius; }

private:
    double m_radius{};
};

